120   * Notes:
   121   *      (1) The BMP file is organized as follows:
   122   *          * 14 byte fileheader
   123   *          * variable size infoheader, from 40 to 124 bytes.  We only use
   124   *            data in he first 40 bytes.
   125   *          * an optional colormap, with size 4 * ncolors (in bytes)
   126   *          * the image data
   127   *      (2) 2 bpp bmp files are not valid in the original spec, but they
   128   *          are valid in later versions.
   129   * </pre>
   130   */
   131  PIX *
   132  pixReadMemBmp(const l_uint8  *cdata,
   133                size_t          size)
   134  {
   135  l_uint8    pel[4];
   136  l_uint8   *cmapBuf, *fdata, *data;
   137  l_int16    bftype, depth, d;
   138  l_int32    offset, ihbytes, width, height, height_neg, xres, yres;
   139  l_int32    compression, imagebytes, cmapbytes, cmapEntries;
   140  l_int32    fdatabpl, extrabytes, pixWpl, pixBpl, i, j, k;
   141  l_uint32  *line, *pixdata, *pword;
   142  l_int64    npixels;
   143  BMP_FH    *bmpfh;
   144  #if defined(__GNUC__)
   145  BMP_HEADER *bmph;
   146  #define bmpih (&bmph->bmpih)
   147  #else
   148  BMP_IH    *bmpih;
   149  #endif
   150  PIX       *pix, *pix1;
   151  PIXCMAP   *cmap;
   152
   153      PROCNAME("pixReadMemBmp");
   154
   155      if (!cdata)
   156          return (PIX *)ERROR_PTR("cdata not defined", procName, NULL);
   157      if (size < sizeof(BMP_FH) + sizeof(BMP_IH))
   158          return (PIX *)ERROR_PTR("bmf size error", procName, NULL);
   159
   160          /* Verify this is an uncompressed bmp */
   161      bmpfh = (BMP_FH *)cdata;
   162      bftype = bmpfh->bfType[0] + ((l_int32)bmpfh->bfType[1] << 8);
   163      if (bftype != BMP_ID)
   164          return (PIX *)ERROR_PTR("not bmf format", procName, NULL);
   165  #if defined(__GNUC__)
   166      bmph = (BMP_HEADER *)bmpfh;
   167  #else
   168      bmpih = (BMP_IH *)(cdata + BMP_FHBYTES);
   169  #endif
   170      compression = convertOnBigEnd32(bmpih->biCompression);
   171      if (compression != 0)
   172          return (PIX *)ERROR_PTR("cannot read compressed BMP files",
   173                                  procName, NULL);
   174
   175          /* Find the offset from the beginning of the file to the image data */
   176      offset = bmpfh->bfOffBits[0];
   177      offset += (l_int32)bmpfh->bfOffBits[1] << 8;
   178      offset += (l_int32)bmpfh->bfOffBits[2] << 16;
   179      offset += (l_uint32)bmpfh->bfOffBits[3] << 24;
   180
   181          /* Read the remaining useful data in the infoheader.
   182           * Note that the first 4 bytes give the infoheader size. */
   183      ihbytes = convertOnBigEnd32(*(l_uint32 *)(bmpih));
   184      width = convertOnBigEnd32(bmpih->biWidth);
   185      height = convertOnBigEnd32(bmpih->biHeight);
   186      depth = convertOnBigEnd16(bmpih->biBitCount);
   187      imagebytes = convertOnBigEnd32(bmpih->biSizeImage);
   188      xres = convertOnBigEnd32(bmpih->biXPelsPerMeter);
   189      yres = convertOnBigEnd32(bmpih->biYPelsPerMeter);
   190
   191          /* Some sanity checking.  We impose limits on the image
   192           * dimensions, resolution and number of pixels.  We make sure the
   193           * file is the correct size to hold the amount of uncompressed data
   194           * that is specified in the header.  The number of colormap
   195           * entries is checked: it can be either 0 (no cmap) or some
   196           * number between 2 and 256.
   197           * Note that the imagebytes for uncompressed images is either
   198           * 0 or the size of the file data.  (The fact that it can
   199           * be 0 is perhaps some legacy glitch). */
   200      if (width < 1)
   201          return (PIX *)ERROR_PTR("width < 1", procName, NULL);
   202      if (width > L_MAX_ALLOWED_WIDTH)
   203          return (PIX *)ERROR_PTR("width too large", procName, NULL);
   204      if (height == 0 || height < -L_MAX_ALLOWED_HEIGHT ||
   205          height > L_MAX_ALLOWED_HEIGHT)
   206          return (PIX *)ERROR_PTR("invalid height", procName, NULL);
   207      if (xres < 0 || xres > L_MAX_ALLOWED_RES ||
   208          yres < 0 || yres > L_MAX_ALLOWED_RES)
   209          return (PIX *)ERROR_PTR("invalid resolution", procName, NULL);
   210      height_neg = 0;
   211      if (height < 0) {
   212          height_neg = 1;
   213          height = -height;
   214      }
   215      npixels = 1LL * width * height;
   216      if (npixels > L_MAX_ALLOWED_PIXELS)
   217          return (PIX *)ERROR_PTR("npixels too large", procName, NULL);
   218      if (depth != 1 && depth != 2 && depth != 4 && depth != 8 &&
   219          depth != 16 && depth != 24 && depth != 32)
   220          return (PIX *)ERROR_PTR("depth not in {1, 2, 4, 8, 16, 24, 32}",
   221                                  procName,NULL);
   222      fdatabpl = 4 * ((1LL * width * depth + 31)/32);
   223      if (imagebytes != 0 && imagebytes != fdatabpl * height)
   224          return (PIX *)ERROR_PTR("invalid imagebytes", procName, NULL);
   225
   226          /* In the original spec, BITMAPINFOHEADER is 40 bytes.
   227           * There have been a number of revisions, to capture more information.
   228           * For example, the fifth version, BITMAPV5HEADER, adds 84 bytes
   229           * of ICC color profiles.  We use the size of the infoheader
   230           * to accommodate these newer formats. */
   231      cmapbytes = offset - BMP_FHBYTES - ihbytes;
   232      cmapEntries = cmapbytes / sizeof(RGBA_QUAD);
   233      if (cmapEntries < 0 || cmapEntries == 1)
   234          return (PIX *)ERROR_PTR("invalid: cmap size < 0 or 1", procName, NULL);
   235      if (cmapEntries > L_MAX_ALLOWED_NUM_COLORS)
   236          return (PIX *)ERROR_PTR("invalid cmap: too large", procName,NULL);
   237      if (size != 1LL * offset + 1LL * fdatabpl * height)
   238          return (PIX *)ERROR_PTR("size incommensurate with image data",
   239                                  procName,NULL);
   240
   241          /* Handle the colormap */
   242      cmapBuf = NULL;
   243      if (cmapEntries > 0) {
   244          if ((cmapBuf = (l_uint8 *)LEPT_CALLOC(cmapEntries, sizeof(RGBA_QUAD)))
   245                   == NULL)
   246              return (PIX *)ERROR_PTR("cmapBuf alloc fail", procName, NULL );
   247
   248              /* Read the colormap entry data from bmp. The RGBA_QUAD colormap
   249               * entries are used for both bmp and leptonica colormaps. */
   250          memcpy(cmapBuf, cdata + BMP_FHBYTES + ihbytes,
   251                 sizeof(RGBA_QUAD) * cmapEntries);
   252      }
   253
   254          /* Make a 32 bpp pix if depth is 24 bpp */
   255      d = (depth == 24) ? 32 : depth;
   256      if ((pix = pixCreate(width, height, d)) == NULL) {
   257          LEPT_FREE(cmapBuf);
   258          return (PIX *)ERROR_PTR( "pix not made", procName, NULL);
   259      }
   260      pixSetXRes(pix, (l_int32)((l_float32)xres / 39.37 + 0.5));  /* to ppi */
   261      pixSetYRes(pix, (l_int32)((l_float32)yres / 39.37 + 0.5));  /* to ppi */
   262      pixSetInputFormat(pix, IFF_BMP);
   263      pixWpl = pixGetWpl(pix);
   264      pixBpl = 4 * pixWpl;
   265
   266          /* Convert the bmp colormap to a pixcmap */
   267      cmap = NULL;
   268      if (cmapEntries > 0) {  /* import the colormap to the pix cmap */
   269          cmap = pixcmapCreate(L_MIN(d, 8));
   270          LEPT_FREE(cmap->array);  /* remove generated cmap array */
   271          cmap->array  = (void *)cmapBuf;  /* and replace */
   272          cmap->n = L_MIN(cmapEntries, 256);
   273          for (i = 0; i < cmap->n; i++)   /* set all colors opaque */
   274              pixcmapSetAlpha (cmap, i, 255);
   275      }
   276      pixSetColormap(pix, cmap);
   277
   278          /* Acquire the image data.  Image origin for bmp is at lower right. */
   279      fdata = (l_uint8 *)cdata + offset;  /* start of the bmp image data */
   280      pixdata = pixGetData(pix);
   281      if (depth != 24) {  /* typ. 1 or 8 bpp */
   282          data = (l_uint8 *)pixdata + pixBpl * (height - 1);
   283          for (i = 0; i < height; i++) {
   284              memcpy(data, fdata, fdatabpl);
   285              fdata += fdatabpl;
   286              data -= pixBpl;
   287          }
   288      } else {  /*  24 bpp file; 32 bpp pix
   289               *  Note: for bmp files, pel[0] is blue, pel[1] is green,
   290               *  and pel[2] is red.  This is opposite to the storage
   291               *  in the pix, which puts the red pixel in the 0 byte,
   292               *  the green in the 1 byte and the blue in the 2 byte.
   293               *  Note also that all words are endian flipped after
   294               *  assignment on L_LITTLE_ENDIAN platforms.
   295               *
   296               *  We can then make these assignments for little endians:
   297               *      SET_DATA_BYTE(pword, 1, pel[0]);      blue
   298               *      SET_DATA_BYTE(pword, 2, pel[1]);      green
   299               *      SET_DATA_BYTE(pword, 3, pel[2]);      red
   300               *  This looks like:
   301               *          3  (R)     2  (G)        1  (B)        0
   302               *      |-----------|------------|-----------|-----------|
   303               *  and after byte flipping:
   304               *           3          2  (B)     1  (G)        0  (R)
   305               *      |-----------|------------|-----------|-----------|
   306               *
   307               *  For big endians we set:
   308               *      SET_DATA_BYTE(pword, 2, pel[0]);      blue
   309               *      SET_DATA_BYTE(pword, 1, pel[1]);      green
   310               *      SET_DATA_BYTE(pword, 0, pel[2]);      red
   311               *  This looks like:
   312               *          0  (R)     1  (G)        2  (B)        3
   313               *      |-----------|------------|-----------|-----------|
   314               *  so in both cases we get the correct assignment in the PIX.
   315               *
   316               *  Can we do a platform-independent assignment?
   317               *  Yes, set the bytes without using macros:
   318               *      *((l_uint8 *)pword) = pel[2];           red
   319               *      *((l_uint8 *)pword + 1) = pel[1];       green
   320               *      *((l_uint8 *)pword + 2) = pel[0];       blue
   960   *          from which we extract the "header" information.
   961   *      (2) The amount of data required depends on the format.  For
   962   *          png, it requires less than 30 bytes, but for jpeg it can
   963   *          require most of the compressed file.  In practice, the data
   964   *          is typically the entire compressed file in memory.
   965   *      (3) findFileFormatBuffer() requires up to 12 bytes to decide on
   966   *          the format, which we require.
   967   * </pre>
   968   */
   969  l_ok
   970  pixReadHeaderMem(const l_uint8  *data,
   971                   size_t          size,
   972                   l_int32        *pformat,
   973                   l_int32        *pw,
   974                   l_int32        *ph,
   975                   l_int32        *pbps,
   976                   l_int32        *pspp,
   977                   l_int32        *piscmap)
   978  {
   979  l_int32  format, ret, w, h, d, bps, spp, iscmap;
   980  l_int32  type;  /* not used */
   981  PIX     *pix;
   982
   983      PROCNAME("pixReadHeaderMem");
   984
   985      if (pw) *pw = 0;
   986      if (ph) *ph = 0;
   987      if (pbps) *pbps = 0;
   988      if (pspp) *pspp = 0;
   989      if (piscmap) *piscmap = 0;
   990      if (pformat) *pformat = 0;
   991      iscmap = 0;  /* init to false */
   992      if (!data)
   993          return ERROR_INT("data not defined", procName, 1);
   994      if (size < 12)
   995          return ERROR_INT("size < 12", procName, 1);
   996
   997      findFileFormatBuffer(data, &format);
   998
   999      switch (format)
  1000      {
  1001      case IFF_BMP:  /* cheating: read the pix */
  1002          if ((pix = pixReadMemBmp(data, size)) == NULL)
  1003              return ERROR_INT( "bmp: pix not read", procName, 1);
  1004          pixGetDimensions(pix, &w, &h, &d);
  1005          pixDestroy(&pix);
  1006          bps = (d == 32) ? 8 : d;
  1007          spp = (d == 32) ? 3 : 1;
  1008          break;
  1009
  1010      case IFF_JFIF_JPEG:
  1011          ret = readHeaderMemJpeg(data, size, &w, &h, &spp, NULL, NULL);
  1012          bps = 8;
  1013          if (ret)
  1014              return ERROR_INT( "jpeg: no header info returned", procName, 1);
  1015          break;
  1016
  1017      case IFF_PNG:
  1018          ret = readHeaderMemPng(data, size, &w, &h, &bps, &spp, &iscmap);
  1019          if (ret)
  1020              return ERROR_INT( "png: no header info returned", procName, 1);
